      "sp.nutrition-diet.s1Img": "../../assets/img/screens/sf-day-es.webp",
      "sp.nutrition-diet.s1Alt": "Pantalla real de la app: tu día tras guardar una comida, con calorías, proteínas, carbohidratos y grasas frente a los objetivos del día",
      "sp.nutrition-diet.s2Img": "../../assets/img/screens/bc-read-es.webp",
